window.TL = {"duration": 423.11, "scenes": [{"id": "s1", "label": "Opening | Key Conclusion", "start": 0, "end": 29.75}, {"id": "s2", "label": "01 | Market Shifts and the Limitations of Traditional Competition", "start": 29.75, "end": 81.76}, {"id": "s3", "label": "02 | Customer Needs and Pain Points", "start": 81.76, "end": 150.3}, {"id": "s4", "label": "03 | Competitor Perceptions and the Learning Design Gap", "start": 150.3, "end": 222.55}, {"id": "s5", "label": "04 | Repositioning: From workbooks to Learning Design", "start": 222.55, "end": 262.92}, {"id": "s6", "label": "05 | Proposed Positioning Statement and Brand Messages", "start": 262.92, "end": 316.74}, {"id": "s7", "label": "06 | Proposed Strategic Actions", "start": 316.74, "end": 393.49}, {"id": "s8", "label": "Closing", "start": 393.49, "end": 423.11}], "cont": ["s1", "s2", "s3", "s4", "s5", "s6", "s7", "s8"], "order": ["l1_1", "l1_2", "l1_3", "l1_4", "l1_5", "l1_6", "l1_7", "l2_1", "l2_2", "l2_3", "l2_4", "l2_5", "l2_6", "l2_7", "l2_8", "l2_9", "l2_10", "l2_11", "l2_12", "l2_13", "l3_1", "l3_2", "l3_3", "l3_4", "l3_5", "l3_6", "l3_7", "l3_8", "l3_9", "l3_10", "l3_11", "l3_12", "l3_13", "l3_14", "l3_15", "l3_16", "l4_1", "l4_2", "l4_3", "l4_4", "l4_5", "l4_6", "l4_7", "l4_8", "l4_9", "l4_10", "l4_11", "l4_12", "l5_1", "l5_2", "l5_3", "l5_4", "l5_5", "l5_6", "l5_7", "l6_1", "l6_2", "l6_3", "l6_4", "l6_5", "l6_6", "l6_7", "l6_8", "l7_1", "l7_2", "l7_3", "l7_4", "l7_5", "l7_6", "l7_7", "l7_8", "l7_9", "l7_10", "l7_11", "l8_1", "l8_2", "l8_3", "l8_4", "l8_5", "l8_6"], "lines": {"l1_1": {"scene": "s1", "text": "Good morning, everyone.", "start": 0.6, "end": 1.77, "words": [["good", 0.53], ["morning", 0.79], ["everyone", 1.01]]}, "l1_2": {"scene": "s1", "text": "I'm Hyuntae Kim.", "start": 2.22, "end": 3.47, "words": [["i'm", 2.14], ["hyun", 2.5], ["tae", 2.7], ["kim", 2.86]]}, "l1_3": {"scene": "s1", "text": "Today, I will share JEI's core repositioning strategy.", "start": 3.92, "end": 7.62, "words": [["today", 3.9], ["i", 4.44], ["will", 4.46], ["share", 4.64], ["jei's", 4.92], ["core", 5.82], ["repositioning", 6.18], ["strategy", 6.86]]}, "l1_4": {"scene": "s1", "text": "Let me start with our key conclusion.", "start": 8.32, "end": 10.28, "words": [["let", 8.24], ["me", 8.52], ["start", 8.66], ["with", 8.92], ["our", 9.08], ["key", 9.22], ["conclusion", 9.42]]}, "l1_5": {"scene": "s1", "text": "JEI must move beyond competing on workbooks, scale, and digital features.", "start": 10.73, "end": 15.48, "words": [["jei", 10.67], ["must", 11.49], ["move", 11.79], ["beyond", 12.03], ["competing", 12.39], ["on", 12.85], ["workbooks", 13.07], ["scale", 13.81], ["and", 14.27], ["digital", 14.33], ["features", 14.69]]}, "l1_6": {"scene": "s1", "text": "Our goal is to become the brand that designs learning to develop children's ability to learn independently.", "start": 15.93, "end": 21.38, "words": [["our", 15.92], ["goal", 16.14], ["is", 16.4], ["to", 16.58], ["become", 16.7], ["the", 16.92], ["brand", 17.1], ["that", 17.48], ["designs", 17.74], ["learning", 18.18], ["to", 18.5], ["develop", 18.68], ["children's", 19.0], ["ability", 19.56], ["to", 19.88], ["learn", 20.1], ["independently", 20.36]]}, "l1_7": {"scene": "s1", "text": "I will explain the market changes, customer needs, the competitive gap, our positioning, and the strategic actions we need to take.", "start": 22.08, "end": 29.2, "words": [["i", 22.08], ["will", 22.2], ["explain", 22.34], ["the", 22.66], ["market", 22.8], ["changes", 23.04], ["customer", 23.76], ["needs", 24.22], ["the", 24.86], ["competitive", 24.94], ["gap", 25.34], ["our", 26.04], ["positioning", 26.34], ["and", 27.14], ["the", 27.18], ["strategic", 27.32], ["actions", 27.68], ["we", 28.14], ["need", 28.4], ["to", 28.56], ["take", 28.68]]}, "l2_1": {"scene": "s2", "text": "First, let’s look at the challenges we face.", "start": 30.65, "end": 33.15, "words": [["first", 30.55], ["let's", 31.29], ["look", 31.53], ["at", 31.65], ["the", 31.77], ["challenges", 31.87], ["we", 32.19], ["face", 32.49]]}, "l2_2": {"scene": "s2", "text": "Three changes are important.", "start": 33.6, "end": 35.19, "words": [["three", 33.56], ["changes", 33.86], ["are", 34.18], ["important", 34.42]]}, "l2_3": {"scene": "s2", "text": "First, the limitations of our business scale.", "start": 35.89, "end": 38.51, "words": [["first", 35.75], ["the", 36.55], ["limitations", 36.65], ["of", 37.09], ["our", 37.45], ["business", 37.57], ["scale", 37.83]]}, "l2_4": {"scene": "s2", "text": "JEI ranks fourth in the workbook market.", "start": 38.96, "end": 41.8, "words": [["jei", 38.87], ["ranks", 39.63], ["fourth", 39.91], ["in", 40.29], ["the", 40.57], ["workbook", 40.67], ["market", 41.15]]}, "l2_5": {"scene": "s2", "text": "We have about 300 locations, while some competitors have more than 700.", "start": 42.25, "end": 46.83, "words": [["we", 42.0], ["have", 42.4], ["about", 42.6], ["300", 42.82], ["locations", 43.22], ["while", 44.3], ["some", 44.52], ["competitors", 44.76], ["have", 45.22], ["more", 45.52], ["than", 45.72], ["700", 45.86]]}, "l2_6": {"scene": "s2", "text": "It is difficult to compete based on size.", "start": 47.28, "end": 49.72, "words": [["it", 47.22], ["is", 47.46], ["difficult", 47.6], ["to", 47.9], ["compete", 48.14], ["based", 48.54], ["on", 48.88], ["size", 49.08]]}, "l2_7": {"scene": "s2", "text": "Second, changes in the market.", "start": 50.42, "end": 52.3, "words": [["second", 50.32], ["changes", 51.12], ["in", 51.52], ["the", 51.7], ["market", 51.78]]}, "l2_8": {"scene": "s2", "text": "There are fewer children entering school, but spending per child is increasing.", "start": 52.75, "end": 57.03, "words": [["there", 52.71], ["are", 52.91], ["fewer", 53.05], ["children", 53.29], ["entering", 53.71], ["school", 54.05], ["but", 54.67], ["spending", 54.89], ["per", 55.25], ["child", 55.51], ["is", 55.87], ["increasing", 56.17]]}, "l2_9": {"scene": "s2", "text": "This means there are fewer customers, but parents are willing to spend more when they see clear value.", "start": 57.48, "end": 62.4, "words": [["this", 57.4], ["means", 57.72], ["there", 57.96], ["are", 58.14], ["fewer", 58.26], ["customers", 58.5], ["but", 59.34], ["parents", 59.4], ["are", 59.78], ["willing", 59.94], ["to", 60.16], ["spend", 60.32], ["more", 60.56], ["when", 60.86], ["they", 61.08], ["see", 61.22], ["clear", 61.44], ["value", 61.7]]}, "l2_10": {"scene": "s2", "text": "Third, similar features across competitors.", "start": 63.1, "end": 65.8, "words": [["third", 63.1], ["similar", 63.62], ["features", 64.06], ["across", 64.44], ["competitors", 64.82]]}, "l2_11": {"scene": "s2", "text": "AI-based assessment, personalized learning paths, and grading have now become standard features.", "start": 66.25, "end": 71.58, "words": [["ai-based", 66.19], ["assessment", 66.87], ["personalized", 67.75], ["learning", 68.21], ["paths", 68.61], ["and", 69.09], ["grading", 69.37], ["have", 69.73], ["now", 70.01], ["become", 70.15], ["standard", 70.45], ["features", 70.81]]}, "l2_12": {"scene": "s2", "text": "As these features become increasingly common, we need a different basis for competition.", "start": 72.03, "end": 76.93, "words": [["as", 71.96], ["these", 72.24], ["features", 72.46], ["become", 72.82], ["increasingly", 73.16], ["common", 73.72], ["we", 74.48], ["need", 74.78], ["a", 74.94], ["different", 75.06], ["basis", 75.34], ["for", 75.76], ["competition", 76.02]]}, "l2_13": {"scene": "s2", "text": "This is why Learning Design is central to our repositioning strategy.", "start": 77.38, "end": 81.21, "words": [["this", 77.32], ["is", 77.56], ["why", 77.7], ["learning", 77.86], ["design", 78.16], ["is", 78.56], ["central", 78.84], ["to", 79.26], ["our", 79.52], ["repositioning", 79.66], ["strategy", 80.4]]}, "l3_1": {"scene": "s3", "text": "So, what are parents really willing to pay for?", "start": 82.66, "end": 85.19, "words": []}, "l3_2": {"scene": "s3", "text": "We can understand parents’ needs in three layers.", "start": 85.64, "end": 88.3, "words": []}, "l3_3": {"scene": "s3", "text": "The first layer is functional needs: learning materials for different levels, connections to school curricula, and learning data.", "start": 89.0, "end": 95.75, "words": []}, "l3_4": {"scene": "s3", "text": "The second layer is emotional needs.", "start": 96.2, "end": 98.23, "words": []}, "l3_5": {"scene": "s3", "text": "Parents want to worry less about their children falling behind.", "start": 98.68, "end": 101.82, "words": []}, "l3_6": {"scene": "s3", "text": "They also want someone to take care of their children’s learning.", "start": 102.27, "end": 105.16, "words": []}, "l3_7": {"scene": "s3", "text": "The third and most important layer is children’s ability to learn on their own.", "start": 105.86, "end": 109.87, "words": []}, "l3_8": {"scene": "s3", "text": "Why do parents discontinue learning programs?", "start": 110.57, "end": 113.11, "words": []}, "l3_9": {"scene": "s3", "text": "Children may become bored with repetitive activities.", "start": 113.56, "end": 116.55, "words": []}, "l3_10": {"scene": "s3", "text": "Standardized learning pace does not always meet individual needs.", "start": 117.0, "end": 120.74, "words": [["standardized", 116.89], ["learning", 117.71], ["pace", 117.95], ["does", 118.31], ["not", 118.53], ["always", 118.81], ["meet", 119.15], ["individual", 119.43], ["needs", 119.83]]}, "l3_11": {"scene": "s3", "text": "Parents struggle to see clear learning outcomes or understand what their children should learn next.", "start": 121.19, "end": 126.4, "words": [["parents", 121.14], ["struggle", 121.56], ["to", 121.92], ["see", 122.14], ["clear", 122.36], ["learning", 122.76], ["outcomes", 123.02], ["or", 123.5], ["understand", 123.92], ["what", 124.4], ["their", 124.7], ["children", 124.9], ["should", 125.22], ["learn", 125.48], ["next", 125.72]]}, "l3_12": {"scene": "s3", "text": "And much of the responsibility for managing their children's learning still falls on the parents.", "start": 126.85, "end": 131.59, "words": [["and", 126.85], ["much", 127.03], ["of", 127.27], ["the", 127.39], ["responsibility", 127.49], ["for", 128.05], ["managing", 128.43], ["their", 128.83], ["children's", 129.11], ["learning", 129.55], ["still", 129.85], ["falls", 130.31], ["on", 130.69], ["the", 130.83], ["parents", 130.91]]}, "l3_13": {"scene": "s3", "text": "These reasons point to one problem.", "start": 132.29, "end": 134.25, "words": [["these", 132.19], ["reasons", 132.57], ["point", 132.91], ["to", 133.21], ["one", 133.35], ["problem", 133.57]]}, "l3_14": {"scene": "s3", "text": "The problem is not simply a lack of learning materials.", "start": 134.7, "end": 137.66, "words": [["the", 134.7], ["problem", 134.82], ["is", 135.1], ["not", 135.3], ["simply", 135.48], ["a", 135.86], ["lack", 136.04], ["of", 136.3], ["learning", 136.48], ["materials", 136.72]]}, "l3_15": {"scene": "s3", "text": "Parents need a clearer understanding of what their children should learn next, why it matters, and how their learning will progress.", "start": 138.11, "end": 144.19, "words": [["parents", 137.98], ["need", 138.5], ["a", 138.66], ["clearer", 138.8], ["understanding", 139.12], ["of", 139.74], ["what", 140.0], ["their", 140.14], ["children", 140.3], ["should", 140.6], ["learn", 140.82], ["next", 141.02], ["why", 141.6], ["it", 141.92], ["matters", 142.06], ["and", 142.58], ["how", 142.72], ["their", 142.86], ["learning", 143.02], ["will", 143.28], ["progress", 143.46]]}, "l3_16": {"scene": "s3", "text": "This is why we must shift our focus from workbooks to how children’s ability to learn improves.", "start": 144.64, "end": 149.75, "words": [["this", 144.52], ["is", 144.9], ["why", 145.06], ["we", 145.26], ["must", 145.44], ["shift", 145.62], ["our", 145.9], ["focus", 146.06], ["from", 146.4], ["workbooks", 146.68], ["to", 147.32], ["how", 147.6], ["children's", 147.76], ["ability", 148.24], ["to", 148.54], ["learn", 148.76], ["improves", 148.96]]}, "l4_1": {"scene": "s4", "text": "Now, let’s look at whether our competitors are meeting this need.", "start": 151.2, "end": 154.77, "words": []}, "l4_2": {"scene": "s4", "text": "These evaluations are based on customer perceptions.", "start": 155.22, "end": 158.23, "words": []}, "l4_3": {"scene": "s4", "text": "Each of our three major competitors is associated with a different strength.", "start": 158.93, "end": 163.09, "words": []}, "l4_4": {"scene": "s4", "text": "Daekyo emphasizes level-based learning, Kumon is known for repetition and building study habits, and Woongjin focuses on online and AI-powered learning platforms.", "start": 163.54, "end": 173.75, "words": []}, "l4_5": {"scene": "s4", "text": "Daekyo does not have a clear long-term learning plan.", "start": 174.45, "end": 177.9, "words": []}, "l4_6": {"scene": "s4", "text": "Kumon can become boring, causing children to lose interest.", "start": 178.35, "end": 181.81, "words": []}, "l4_7": {"scene": "s4", "text": "Woongjin's platform may feel complex, while screen-based learning can raise concerns about insufficient handwriting practice.", "start": 182.26, "end": 188.79, "words": []}, "l4_8": {"scene": "s4", "text": "Above all, no company clearly answers the question parents really ask: “Where should my child’s learning be in three years?”", "start": 189.49, "end": 196.25, "words": []}, "l4_9": {"scene": "s4", "text": "This is where “Design” comes in.", "start": 196.7, "end": 198.3, "words": []}, "l4_10": {"scene": "s4", "text": "It means setting a direction after diagnosis and helping children stay motivated along the way.", "start": 198.75, "end": 203.92, "words": []}, "l4_11": {"scene": "s4", "text": "According to Al Ries’s positioning principles, it is very difficult for a company ranked fourth to beat the leader in the same category.", "start": 204.62, "end": 211.44, "words": []}, "l4_12": {"scene": "s4", "text": "Rather than trying to move up the existing competitive ladder, JEI aims to establish a new ladder centered on Learning Design—one where we can build a distinctive leadership position.", "start": 211.89, "end": 222.0, "words": []}, "l5_1": {"scene": "s5", "text": "We will move from selling workbooks to providing Learning Design.", "start": 223.45, "end": 226.92, "words": []}, "l5_2": {"scene": "s5", "text": "We aim to provide personalized learning roadmaps that help each child understand what to learn next and how to progress.", "start": 227.37, "end": 233.8, "words": []}, "l5_3": {"scene": "s5", "text": "We will build on our existing strengths: the JEI Self-Learning Method, diagnostic assessment, and structured learning materials.", "start": 234.5, "end": 241.64, "words": []}, "l5_4": {"scene": "s5", "text": "But we will define self-learning as an ability, not just the act of studying.", "start": 242.09, "end": 246.23, "words": []}, "l5_5": {"scene": "s5", "text": "This builds on the nearly 50-year legacy of the JEI Self-Learning Method.", "start": 246.68, "end": 251.32, "words": []}, "l5_6": {"scene": "s5", "text": "Our focus is not simply to have more locations or members than competitors.", "start": 252.02, "end": 256.38, "words": []}, "l5_7": {"scene": "s5", "text": "We want to create clear learning paths for individual students and become a leader in the Learning Design category.", "start": 256.83, "end": 262.37, "words": []}, "l6_1": {"scene": "s6", "text": "Our proposed positioning statement is: \"JEI designs learning to develop children's ability to learn independently.\"", "start": 263.82, "end": 270.21, "words": []}, "l6_2": {"scene": "s6", "text": "This statement reflects our shift from simply providing workbooks to developing children's Self-Learning Ability through Learning Design.", "start": 270.91, "end": 277.79, "words": []}, "l6_3": {"scene": "s6", "text": "Our brand messaging is built around two key concepts: \"Design\" and \"Self-Learning Ability.\"", "start": 278.49, "end": 283.69, "words": []}, "l6_4": {"scene": "s6", "text": "We have proposed several slogan options, including \"Learning starts with design,\" \"Studying starts with design,\" and \"Beyond Workbooks. Toward Learning Design.\"", "start": 284.39, "end": 293.03, "words": []}, "l6_5": {"scene": "s6", "text": "Our proposed campaign message is: \"It's not a lack of ability. It's a lack of learning design.\"", "start": 293.73, "end": 299.06, "words": []}, "l6_6": {"scene": "s6", "text": "And our customer value message is: \"The ability to learn independently begins with Learning Design.\"", "start": 299.76, "end": 305.2, "words": []}, "l6_7": {"scene": "s6", "text": "These are proposed expressions, not finalized brand slogans.", "start": 305.9, "end": 309.59, "words": []}, "l6_8": {"scene": "s6", "text": "Whatever we ultimately choose, our messages must reinforce a clear and consistent position in customers' minds.", "start": 310.04, "end": 316.19, "words": []}, "l7_1": {"scene": "s7", "text": "Finally, let me outline five strategic priorities for execution.", "start": 317.64, "end": 321.66, "words": []}, "l7_2": {"scene": "s7", "text": "First, we will focus on our strongest core subjects rather than promoting all 17 subjects equally.", "start": 322.36, "end": 328.06, "words": []}, "l7_3": {"scene": "s7", "text": "This will allow us to build a clear and differentiated Learning Design approach.", "start": 328.51, "end": 332.69, "words": []}, "l7_4": {"scene": "s7", "text": "Second, we will strengthen the connection between assessment, Learning Design, and coaching.", "start": 333.39, "end": 338.39, "words": []}, "l7_5": {"scene": "s7", "text": "Each child's learning needs will be assessed, the next learning steps will be designed, and instructors will provide personalized guidance along the way.", "start": 338.84, "end": 347.36, "words": []}, "l7_6": {"scene": "s7", "text": "Third, we will continue to emphasize the role of our instructors.", "start": 348.06, "end": 351.79, "words": []}, "l7_7": {"scene": "s7", "text": "While AI-powered learning solutions are important, personal guidance and ongoing learning support remain key reasons why parents choose JEI.", "start": 352.24, "end": 360.01, "words": []}, "l7_8": {"scene": "s7", "text": "Fourth, we will communicate a consistent brand message across our products, learning centers, local offices, and advertising.", "start": 360.71, "end": 367.39, "words": []}, "l7_9": {"scene": "s7", "text": "\"Design\" and \"Self-Learning Ability\" should remain central to how we present our brand.", "start": 367.84, "end": 372.4, "words": []}, "l7_10": {"scene": "s7", "text": "Fifth, we will focus on increasing value per customer and recognize the importance of multi-subject learning, while avoiding competition based solely on the number of subjects or overall business scale.", "start": 373.1, "end": 384.54, "words": []}, "l7_11": {"scene": "s7", "text": "Together, these priorities will help JEI strengthen its position in Learning Design and deliver greater value to children and their families.", "start": 385.24, "end": 392.94, "words": []}, "l8_1": {"scene": "s8", "text": "To summarize, JEI aims to move beyond workbooks and establish a leadership position in Learning Design by designing learning to develop children's ability to learn independently.", "start": 394.39, "end": 404.51, "words": []}, "l8_2": {"scene": "s8", "text": "To achieve this, we must change first.", "start": 405.21, "end": 407.55, "words": []}, "l8_3": {"scene": "s8", "text": "When we develop products, meet customers, and discuss ideas in meetings, we must all use the same language.", "start": 408.0, "end": 413.62, "words": []}, "l8_4": {"scene": "s8", "text": "Starting today, our shared message is “Designing the Ability to Learn.”", "start": 414.07, "end": 417.92, "words": []}, "l8_5": {"scene": "s8", "text": "Thank you.", "start": 418.62, "end": 419.28, "words": []}, "l8_6": {"scene": "s8", "text": "Please feel free to ask any questions.", "start": 419.73, "end": 421.91, "words": []}}};
